use strict;
use warnings;
use Test::More;
use File::Spec;
use ArchivePaths;

sub corsair_marker {
    open(my $fh, '>', "$ENV{CORSAIR_MARKER_DIR}/$_[0]") or die "marker $_[0]: $!";
    print $fh $_[1] if defined $_[1];
    close($fh);
}

corsair_marker('start');
my $dest = eval { ArchivePaths::destination('out', '../../etc/cron.d/job') };
my $rejected = $@ ? 1 : 0;
my $holds = !$rejected && defined $dest && index(File::Spec->rel2abs($dest), File::Spec->rel2abs('out') . '/') != 0;
corsair_marker('check', $holds ? 'holds' : 'violated');
ok($holds, 'security_entry_escapes_destination') or diag($ENV{CORSAIR_TOKEN});
corsair_marker('end') if Test::More->builder->is_passing;
done_testing();

