package ArchivePaths;
# Where each entry of an uploaded archive is extracted.
use strict;
use warnings;
use File::Spec;

sub destination {
    my ($dest, $entry_name) = @_;
    return File::Spec->catfile($dest, $entry_name);
}

1;

use strict;
use warnings;
use Test::More;
use ArchivePaths;

is(ArchivePaths::destination('out', 'a.txt'), 'out/a.txt', 'joins an entry');

done_testing();
